#define main prior_graph_main
#include "graph-check.cpp"
#undef main
extern "C" void studio_roots_geometry(bool);
int main(int argc,char **argv){if(argc!=2||std::filesystem::exists(argv[1]))return 2;checks=obs_data_array_create();check(obs_startup("en-US",nullptr,nullptr),"Real core startup for real scene/group APIs");obs_source_info i{};i.id="graph_probe";i.type=OBS_SOURCE_TYPE_INPUT;i.output_flags=OBS_SOURCE_AUDIO;i.get_name=name;i.create=create;i.destroy=destroy;i.enum_active_sources=enumerate;i.enum_all_sources=enumerate;obs_register_source(&i);studio_roots_geometry(true);
 auto *s=obs_scene_create_private("actual parent");auto *leaf=source("actual leaf");auto *item=obs_scene_add(s,leaf);auto *g=obs_scene_add_group(s,"actual group");auto *gs=obs_sceneitem_get_source(g);obs_source_inc_active(obs_scene_get_source(s));count(leaf,1,1,"Actual scene insertion inherits MAIN");obs_sceneitem_group_add_item(g,item);check(obs_sceneitem_get_scene(item)==obs_sceneitem_group_get_scene(g),"Actual group_add_item changes visual parent");count(leaf,1,1,"Actual group_add_item preserves inherited MAIN");obs_source_inc_showing(gs);count(leaf,2,1,"Direct AUX on actual group reaches physically reparented child");obs_sceneitem_group_remove_item(g,item);check(obs_sceneitem_get_scene(item)==s,"Actual group_remove_item changes visual parent");count(leaf,1,1,"Actual group_remove_item stops group AUX contribution");obs_source_dec_showing(gs);obs_sceneitem_t *members[]={item};auto *g2=obs_scene_insert_group(s,"inserted actual group",members,1);auto *g2s=obs_sceneitem_get_source(g2);obs_source_inc_showing(g2s);count(leaf,2,1,"Actual insert_group transfers edge to new group");obs_source_dec_showing(g2s);
 // Real reorder moves child out of inserted group, preserving ownership.
 obs_sceneitem_order_info order[]={{nullptr,g},{nullptr,g2},{nullptr,item}};check(obs_scene_reorder_items2(s,order,3),"Actual reorder_items2 ungroups child");obs_source_inc_showing(g2s);count(leaf,1,1,"Actual reorder moved child stops former group AUX");obs_source_dec_showing(g2s);
 // Move into group by reorder, then ungroup through the actual API.
 obs_sceneitem_order_info into[]={{nullptr,g},{g,item},{nullptr,g2}};check(obs_scene_reorder_items2(s,into,3),"Actual reorder_items2 places child in group");obs_source_inc_showing(gs);count(leaf,2,1,"Actual reorder moved child inherits group AUX");obs_source_dec_showing(gs);
 obs_sceneitem_group_add_item(g,g);check(obs_sceneitem_get_scene(g)==s,"Actual group self-drop refuses structural cycle");auto *alias=obs_scene_add(s,gs);obs_sceneitem_group_add_item(g,alias);check(obs_sceneitem_get_scene(alias)==s,"Actual duplicate-source drop refuses same-source structural cycle");obs_sceneitem_remove(alias);
 obs_sceneitem_group_add_item(g,g2);check(obs_sceneitem_get_scene(g2)==obs_sceneitem_group_get_scene(g),"Actual API nests a group");obs_source_inc_showing(gs);count(g2s,2,1,"Nested group inherits outer AUX");obs_source_dec_showing(gs);obs_sceneitem_group_remove_item(g,g2);check(obs_sceneitem_get_scene(g2)==s,"Actual API unnests a group");count(g2s,1,1,"Unnested group retains only root MAIN");
 obs_sceneitem_group_ungroup(g);count(leaf,1,1,"Actual ungroup removes old group credit without duplication");obs_source_dec_active(obs_scene_get_source(s));count(leaf,0,0,"All real scene/group path credits return to zero");obs_scene_release(s);obs_source_release(leaf);studio_graph_drain();check(destroyed==1,"Real scene/group destruction releases owned synthetic leaf");studio_roots_geometry(false);obs_shutdown();auto *d=obs_data_create();obs_data_set_array(d,"checks",checks);obs_data_set_int(d,"failures",failures);obs_data_set_bool(d,"passed",!failures);obs_data_save_json_safe(d,argv[1],"tmp",nullptr);obs_data_release(d);obs_data_array_release(checks);return failures?1:0;}
